        n = await _scalar("SELECT COUNT(*) FROM receipts WHERE \"DN_No\" LIKE 'SVCJ-%'")
        check("aj: exactly one SVCJ ledger row exists after all passes", n == 1, f"got {n}")

        # ── 2026-07-14 workbook restructure: columns resolve by NAME ────────
